eel interessante blogartikelen en reviews tegen. Check wat wij de beste verzorgingsproducten vinden, schaf die producten aan en verzorg jezelf hiermee tot in de puntjes!</p>"},"elements":[],"widgetType":"text-editor"}],"isInner":false}],"isInner":false},{"id":"4af0d7a","elType":"section","settings":{"margin":{"unit":"px","top":"0","right":0,"bottom":"0","left":0,"isLinked":false},"padding":{"unit":"px","top":"100","right":"0","bottom":"14","left":"0","isLinked":false},"padding_mobile":{"unit":"px","top":"36","right":"0","bottom":"0","left":"0","isLinked":false},"background_background":"classic","__globals__":{"background_color":""},"padding_tablet":{"unit":"px","top":"72","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[{"id":"5edb725","elType":"column","settings":{"_column_size":100,"_inline_size":null,"margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[{"id":"8148b04","elType":"widget","settings":{"title":"Categorieën","title_color":"#0D3C00","_margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_element_width":"inherit","_element_width_mobile":"inherit","_element_custom_width":{"unit":"%","size":52,"sizes":[]},"align":"left","_padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"_element_width_tablet":"inherit","__globals__":{"title_color":"globals/colors?id=primary","typography_typography":""},"typography_typography":"custom","typography_font_family":"Quicksand","typography_font_weight":"700","_padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"10","isLinked":false}},"elements":[],"widgetType":"heading"}],"isInner":false}],"isInner":false},{"id":"25dcc8ad","elType":"section","settings":{"structure":"40","padding":{"unit":"px","top":"0","right":"0","bottom":"0124","left":"0","isLinked":false},"_element_id":"blok1","background_background":"classic","padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"036"